/**
 * social-testimonial — animated quote card with word-by-word text reveal.
 *
 * Converted from Remotion TestimonialCard pattern. Dark card with large
 * quotation mark, word-by-word quote reveal, horizontal divider, and
 * author avatar + name section. No TextOverlay — text is integral to the visual.
 *
 * Block structure (docs/blocks.md):
 *   background — SceneBackground + accent radial glow behind the card
 *   hero       — TestimonialCard primitive (quote mark, word-by-word quote,
 *                divider, author row; text integral — no caption slot)
 */
import type { SceneTemplateProps } from "./types";
import { resolveTokens } from "../theme";
import { withOpacity } from "../theme";
import { SceneBackground, getMediaBackgroundProps } from "./scene-background";
import { stripPipe } from "../typography";
import { TestimonialCard } from "../primitives/social/TestimonialCard";

export const SocialTestimonialTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  beatIntensity,
  width,
  height,
  sceneDuration,
  isPlaying = true,
}) => {
  const dim = Math.min(width, height);
  const { primary, foreground, font, surfaceElevated, muted } = resolveTokens(style);

  const quote = stripPipe(String(variables.quote || ""));
  const gradSeed = quote.split("").reduce((acc: number, c: string) => acc + c.charCodeAt(0), 0);
  const authorName = String(variables.authorName || "Jessica Torres");
  const authorRole = String(variables.authorRole || "");
  const avatarBg = primary;

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: "#000",
        position: "relative",
        overflow: "hidden",
        fontFamily: font,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* [slot: background] Gradient / media backdrop */}
      <SceneBackground
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        width={width}
        height={height}
        {...getMediaBackgroundProps(variables)}
        seed={gradSeed}
        isPlaying={isPlaying}
        beatIntensity={beatIntensity}
      />
      {/* [slot: background] Glow behind card — large radial gradient (replaces filter: blur) */}
      <div
        style={{
          position: "absolute",
          width: dim * 0.9,
          height: dim * 0.7,
          borderRadius: "50%",
          background: `radial-gradient(ellipse, ${withOpacity(primary, 0.15)} 0%, ${withOpacity(primary, 0.05)} 40%, transparent 70%)`,
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          pointerEvents: "none",
        }}
      />

      {/* [slot: hero] Quote card — shared primitive */}
      <TestimonialCard
        progress={progress}
        quote={quote}
        authorName={authorName}
        authorRole={authorRole}
        avatarColor={avatarBg}
        accent={primary}
        surfaceElevated={surfaceElevated}
        foreground={foreground}
        muted={muted}
        width={width}
        height={height}
        beatIntensity={beatIntensity}
      />
    </div>
  );
};

/**
 * TestimonialCard
 *
 * Dark card with a quote mark + word-by-word quote + horizontal divider
 * + author block (avatar + name + role). Card scales in, quote mark
 * pops, quote reveals word-by-word, divider expands, author rises in.
 *
 * This is the ONE implementation:
 * social-testimonial.tsx composes this component (background glow +
 * SceneBackground stay in the template), so template fixes reach
 * custom scenes and vice versa.
 */

import * as React from "react";
import { interpolate, spring, SPRING_SMOOTH, SPRING_SNAPPY } from "../../motion";
import { accessibleTextColor, autoTextColor } from "../../theme";
import { stripPipe } from "../../typography";
// `lighten` centralizes the color adjustment — for integer
// RGB channels round(v + x) ≡ v + round(x), so the two are bit-identical.
import { TOKEN_DEFAULTS, lighten } from "../../theme";

const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

// ─── Typed component (direct use from templates) ────────────────

export interface TestimonialCardProps {
  /** Scene progress 0→1 */
  progress: number;
  /** The testimonial quote */
  quote: string;
  /** Author name (initial used in avatar) */
  authorName: string;
  /** Author role / title (optional, rendered as a smaller line below name) */
  authorRole?: string;
  /** Avatar background color. Defaults to "#ec4899". */
  avatarColor?: string;
  /** Accent color for the quote mark. Defaults to "#00e5a0". */
  accent?: string;
  /** Explicit brand-kit elevated surface for the card fill. Falls back to
   *  the tuned near-black card. */
  surfaceElevated?: string;
  /** Resolved semantic foreground, used when it is accessible on the card. */
  foreground?: string;
  /** Explicit brand-kit muted text color for the role line. */
  muted?: string;
  /** Frame width */
  width: number;
  /** Frame height */
  height: number;
  /** Beat pulse 0→1 */
  beatIntensity?: number;
}

export const TestimonialCard: React.FC<TestimonialCardProps> = ({
  progress,
  quote: rawQuote,
  authorName: rawAuthorName,
  authorRole: rawAuthorRole = "",
  avatarColor = "#ec4899",
  accent = TOKEN_DEFAULTS.primary,
  surfaceElevated,
  foreground,
  muted,
  width,
  height,
  beatIntensity = 0,
}) => {
  const dim = Math.min(width, height);
  const s = dim / 1080;

  const quote = stripPipe(rawQuote || "");
  const authorName = stripPipe(rawAuthorName || "");
  const authorRole = stripPipe(rawAuthorRole || "");
  const initialChar = authorName.charAt(0).toUpperCase();

  // Card colors — solid dark; explicit brand-kit values win when set
  const cardBg = surfaceElevated || lighten("#0a0a0f", 0.08);
  const borderColor = lighten("#0a0a0f", 0.15);
  const textPrimary = accessibleTextColor(cardBg, foreground);
  const textSecondary = accessibleTextColor(cardBg, muted);

  // Quotation mark entrance
  const quoteMarkP = spring(interpolate(progress, [0.02, 0.2], [0, 1], CLAMP), SPRING_SNAPPY);
  const quoteMarkScale = interpolate(quoteMarkP, [0, 1], [0.3, 1]);
  const quoteMarkOpacity = quoteMarkP;

  // Horizontal divider expand
  const lineWidth = interpolate(progress, [0.35, 0.55], [0, 100], CLAMP);

  // Author entrance
  const authorP = spring(interpolate(progress, [0.45, 0.7], [0, 1], CLAMP), SPRING_SMOOTH);
  const authorY = interpolate(authorP, [0, 1], [20 * s, 0]);
  const authorOpacity = authorP;

  // Card dimensions
  const cardWidth = Math.min(width * 0.75, dim * 0.85);
  const cardPad = dim * 0.045;
  const avatarSize = dim * 0.055;

  // Card entrance
  const cardP = spring(interpolate(progress, [0, 0.15], [0, 1], CLAMP), SPRING_SMOOTH);
  const cardScale = interpolate(cardP, [0, 1], [0.92, 1]);
  const cardOpacity = interpolate(cardP, [0, 1], [0, 1]);

  const beatScale = 1 + beatIntensity * 0.01;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: cardWidth,
          padding: cardPad,
          backgroundColor: cardBg,
          borderRadius: dim * 0.02,
          border: `1px solid ${borderColor}`,
          boxShadow: `0 ${dim * 0.01}px ${dim * 0.04}px rgba(0,0,0,0.4)`,
          position: "relative",
          zIndex: 1,
          transform: `scale(${cardScale * beatScale})`,
          opacity: cardOpacity,
        }}
      >
        {/* Quotation mark */}
        <div
          style={{
            fontSize: dim * 0.08,
            lineHeight: 0.8,
            color: accent,
            fontWeight: 700,
            marginBottom: dim * 0.018,
            transform: `scale(${quoteMarkScale})`,
            opacity: quoteMarkOpacity,
            transformOrigin: "left top",
          }}
        >
          {"“"}
        </div>

        {/* Quote — word-by-word reveal */}
        <div
          style={{
            fontSize: dim * 0.038,
            lineHeight: 1.6,
            color: textPrimary,
            fontWeight: 500,
            marginBottom: dim * 0.032,
            display: "flex",
            flexWrap: "wrap",
            gap: `0 ${dim * 0.007}px`,
          }}
        >
          {quote.split(/\s+/).filter(Boolean).map((word, i, arr) => {
            const wStart = 0.20 + i * (0.30 / Math.max(arr.length, 1));
            const wEnd = Math.min(wStart + 0.08, 0.55);
            const wordOpacity = interpolate(progress, [wStart, wEnd], [0, 1], CLAMP);
            const wordY = interpolate(progress, [wStart, wEnd], [8 * s, 0], CLAMP);
            return (
              <span
                key={i}
                style={{
                  opacity: wordOpacity,
                  transform: `translateY(${wordY}px)`,
                  display: "inline-block",
                }}
              >
                {word}
              </span>
            );
          })}
        </div>

        {/* Horizontal divider */}
        <div style={{ display: "flex", justifyContent: "center", marginBottom: dim * 0.028 }}>
          <div style={{ height: 1, width: `${lineWidth}%`, backgroundColor: borderColor }} />
        </div>

        {/* Author section */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: dim * 0.016,
            opacity: authorOpacity,
            transform: `translateY(${authorY}px)`,
          }}
        >
          <div
            style={{
              width: avatarSize,
              height: avatarSize,
              borderRadius: "50%",
              backgroundColor: avatarColor,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: avatarSize * 0.45,
              fontWeight: 700,
              color: autoTextColor(avatarColor),
              flexShrink: 0,
            }}
          >
            {initialChar}
          </div>
          <div>
            <div
              style={{
                fontSize: dim * 0.032,
                fontWeight: 600,
                color: textPrimary,
                marginBottom: dim * 0.003,
              }}
            >
              {authorName}
            </div>
            {authorRole && (
              <div style={{ fontSize: dim * 0.024, color: textSecondary }}>{authorRole}</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * SceneBackground — shared backdrop component for any scene template that
 * wants to support both a brand-color gradient and stock media (Pexels
 * photo / video) as an alternate atmosphere.
 *
 * Usage:
 *   <SceneBackground
 *     style={style}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     mediaUrl={String(variables.mediaUrl || "")}
 *     mediaType={String(variables.mediaType || "auto")}
 *     seed={String(variables.texts || "")}
 *     isPlaying={isPlaying}
 *   />
 *   ... template's content layered on top
 *
 * Behavior:
 *   - Brand gradient is the always-on backdrop (uses BrandGradientOverlay).
 *   - When mediaUrl is set and mediaType isn't "gradient", the photo/video
 *     covers the gradient. Legibility is then split between two instruments:
 *     eased scrims shaped to where the template's copy sits (`textAnchor`),
 *     and a per-glyph halo on the type itself (MEDIA_TEXT_SHADOW). Neither
 *     alone can hold white type over a blown-out highlight without flattening
 *     the picture; together they do it at roughly half the darkening.
 *   - mediaType="gradient" deliberately ignores mediaUrl and renders only
 *     the brand gradient. First-class atmospheric mode.
 *   - When mediaUrl is empty / 404s / Pexels search returned nothing,
 *     gradient shows through cleanly (matches every other gradient-backed
 *     template).
 *
 * Extracted from bg-media.tsx so any template can compose it. bg-media
 * now uses this component too — its "media is the scene" identity comes
 * from how it positions the title (centered, full-frame), not from
 * duplicated render logic.
 */

import React, { useEffect, useRef } from "react";
import type { TemplateStyle } from "../template-context";
import { BrandGradientOverlay } from "../backgrounds";
import { getBackgroundTransform } from "../backgrounds";

const VIDEO_EXTENSIONS = [".mp4", ".webm", ".mov", ".m4v", ".avi"];

function isVideoUrl(url: string): boolean {
  try {
    const pathname = new URL(url).pathname.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => pathname.endsWith(ext));
  } catch {
    const lower = url.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => lower.endsWith(ext));
  }
}

export type ResolvedMediaType = "photo" | "video" | "gradient";

export type MediaPosition = "center" | "top" | "bottom" | "left" | "right";
export type MediaTreatment = "subtle" | "cinematic" | "text-safe";

const MEDIA_POSITIONS: Record<MediaPosition, string> = {
  center: "center center",
  top: "center top",
  bottom: "center bottom",
  left: "left center",
  right: "right center",
};

export function resolveMediaPosition(value: string): string {
  return MEDIA_POSITIONS[value as MediaPosition] ?? MEDIA_POSITIONS.center;
}

export function resolveMediaTreatment(value: string): MediaTreatment {
  return value === "subtle" || value === "text-safe" ? value : "cinematic";
}

export interface MediaTreatmentLayer {
  id: "vignette" | "center-scrim" | "bottom-scrim";
  background: string;
  style?: React.CSSProperties;
}

/**
 * Where the template puts its type. The scrim is shaped to the copy, not to
 * the frame: darkening picture the type never touches costs contrast in the
 * photo and buys no legibility. "full" is the conservative default for
 * templates that have not declared an anchor.
 */
export type MediaTextAnchor = "center" | "bottom" | "full";

/**
 * Smoothstep-sampled alpha stops between `start`% and `end`% of the gradient
 * box, held at full strength before `start` and after `end`.
 *
 * A two-stop `rgba(0,0,0,a) → transparent` scrim ramps alpha linearly, so it
 * ends with a constant slope. Lateral inhibition in the eye amplifies that
 * slope discontinuity into a visible band — the grey bar cutting across the
 * frame that makes an overlay read as an overlay. Smoothstep flattens the
 * curve at both ends, so the scrim holds where the type sits and then leaves
 * without an edge: the same peak coverage over the copy, noticeably less of
 * the picture spent getting there.
 */
const SCRIM_STOP_COUNT = 7;

function smoothstep(t: number): number {
  return t * t * (3 - 2 * t);
}

function easedStops(
  peakAlpha: number,
  start: number,
  end: number,
  direction: "fade-out" | "fade-in",
): string {
  const alphaAt = (t: number): string => {
    const eased = direction === "fade-out" ? 1 - smoothstep(t) : smoothstep(t);
    return `rgba(0,0,0,${Number((peakAlpha * eased).toFixed(3))})`;
  };
  const stops: string[] = [];
  if (start > 0) stops.push(`${alphaAt(0)} 0%`);
  for (let i = 0; i < SCRIM_STOP_COUNT; i += 1) {
    const t = i / (SCRIM_STOP_COUNT - 1);
    const position = Number((start + (end - start) * t).toFixed(2));
    stops.push(`${alphaAt(t)} ${position}%`);
  }
  if (end < 100) stops.push(`${alphaAt(1)} 100%`);
  return stops.join(", ");
}

/**
 * Export-safe contrast recipes. Overlays only: SVG capture cannot rely on CSS
 * filters, so a blur-behind-text plate is off the table.
 *
 * The scrims deliberately stop short of solving legibility on their own. A
 * uniform darkening strong enough to carry white type over a blown-out sky
 * needs roughly 0.8 alpha — at that point the photo is a texture, not a
 * picture. The cheaper half of the job belongs to the type: a per-glyph halo
 * (MEDIA_TEXT_SHADOW) buys local contrast exactly where it is needed and
 * costs the image nothing. Scrim for the plate, halo for the glyph.
 */
export function getMediaTreatmentLayers(
  value: string,
  anchor: MediaTextAnchor = "full",
): MediaTreatmentLayer[] {
  const treatment = resolveMediaTreatment(value);
  const vignette: MediaTreatmentLayer = {
    id: "vignette",
    background:
      treatment === "subtle"
        ? `radial-gradient(ellipse at center, ${easedStops(0.28, 45, 100, "fade-in")})`
        : `radial-gradient(ellipse at center, ${easedStops(0.72, 32, 100, "fade-in")})`,
  };
  if (treatment === "subtle") return [vignette];

  const textSafe = treatment === "text-safe";
  const layers: MediaTreatmentLayer[] = [vignette];

  if (anchor !== "bottom") {
    layers.push({
      id: "center-scrim",
      background: textSafe
        ? `radial-gradient(ellipse 92% 58% at 50% 50%, ${easedStops(0.46, 34, 90, "fade-out")})`
        : `radial-gradient(ellipse 88% 52% at 50% 50%, ${easedStops(0.26, 30, 88, "fade-out")})`,
    });
  }

  if (anchor !== "center") {
    layers.push({
      id: "bottom-scrim",
      background: `linear-gradient(to top, ${easedStops(textSafe ? 0.64 : 0.5, 8, 100, "fade-out")})`,
      style: { top: "55%" },
    });
  }

  return layers;
}

export function resolveMediaType(
  mediaType: string,
  mediaUrl: string,
): ResolvedMediaType {
  if (mediaType === "gradient") return "gradient";
  if (mediaType === "video") return "video";
  if (mediaType === "photo") return "photo";
  // "auto" — detect from URL extension
  return mediaUrl && isVideoUrl(mediaUrl) ? "video" : "photo";
}

/**
 * True when the scene actually renders a photo or video backdrop — i.e. a
 * mediaUrl is set and the template has not been pinned to the brand gradient.
 * Templates use it to switch their type onto the media legibility recipe.
 */
export function hasSceneMedia(variables: Record<string, unknown>): boolean {
  return (
    String(variables.mediaUrl || "").trim() !== "" &&
    String(variables.mediaType || "auto") !== "gradient"
  );
}

export function getMediaBackgroundProps(variables: Record<string, unknown>) {
  return {
    mediaUrl: String(variables.mediaUrl || ""),
    mediaType: String(variables.mediaType || "auto"),
    mediaPoster: String(variables.mediaPoster || ""),
    mediaPosition: String(variables.mediaPosition || "center"),
    mediaTreatment: String(variables.mediaTreatment || "cinematic"),
  };
}

export interface SceneBackgroundProps {
  style: TemplateStyle;
  progress: number;
  sceneDuration?: number;
  width: number;
  height: number;
  mediaUrl?: string;
  mediaType?: string;
  /** Still image URL shown while the <video> backdrop decodes its first
   *  frame. Without it the element renders transparent during the
   *  ~50–400ms decode window and the gradient flashes through. */
  mediaPoster?: string;
  /** Cover-crop focal anchor. Keeps the important edge/subject visible. */
  mediaPosition?: string;
  /** Overlay recipe: subtle, cinematic, or stronger text-safe contrast. */
  mediaTreatment?: string;
  /** Where this template's copy sits, so the scrim is shaped to the type
   *  instead of to the frame. Defaults to "full" (scrim both the middle and
   *  the lower third) for templates that have not declared an anchor. */
  textAnchor?: MediaTextAnchor;
  /** Background motion effect (drift / pulse / Ken Burns). Applied to the photo/video. */
  backgroundEffect?: string;
  /** Stable seed for the gradient breathing animation. Pass the scene's
   *  text content (or any stable string) — it's hashed deterministically. */
  seed?: number | string;
  /** Pause video when preview is paused. Defaults to true (export path). */
  isPlaying?: boolean;
  beatIntensity?: number;
}

export const SceneBackground: React.FC<SceneBackgroundProps> = ({
  style,
  progress,
  sceneDuration,
  width: _width, // accepted for symmetry; not currently used in render
  height: _height,
  mediaUrl = "",
  mediaType = "auto",
  mediaPoster,
  mediaPosition = "center",
  mediaTreatment = "cinematic",
  textAnchor = "full",
  backgroundEffect,
  seed,
  isPlaying = true,
  beatIntensity = 0,
}) => {
  void _width;
  void _height;
  const resolved = resolveMediaType(mediaType, mediaUrl);
  const showMedia = resolved !== "gradient" && !!mediaUrl;
  const resolvedPosition = resolveMediaPosition(mediaPosition);
  const resolvedTreatment = resolveMediaTreatment(mediaTreatment);
  const treatmentLayers = getMediaTreatmentLayers(resolvedTreatment, textAnchor);

  const gradSeed =
    typeof seed === "number"
      ? seed
      : typeof seed === "string"
        ? seed.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0)
        : 0;

  const bgTransform = getBackgroundTransform(
    backgroundEffect,
    progress,
    beatIntensity,
  );

  // Video playback control — same pause/seek logic bg-media used pre-extract.
  const videoRef = useRef<HTMLVideoElement>(null);
  const lastProgress = useRef(progress);
  const videoStarted = useRef(false);

  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;
    if (!isPlaying) {
      vid.pause();
      videoStarted.current = false;
      return;
    }
    const progressChanged = Math.abs(progress - lastProgress.current) > 0.001;
    lastProgress.current = progress;
    if (progressChanged && !videoStarted.current) {
      vid.playbackRate = 1;
      vid.currentTime = 0;
      vid.play().catch(() => {});
      videoStarted.current = true;
    } else if (!progressChanged && videoStarted.current) {
      vid.pause();
      videoStarted.current = false;
    }
  }, [progress, isPlaying]);

  // Release the decoder on unmount. Without this, iOS Safari keeps the
  // video's decoder buffer alive after the React node is gone — each
  // scene transition (or play/pause/play cycle that remounts the active
  // scene) leaks one decoder, eventually crossing the renderer's memory
  // ceiling and triggering "A problem repeatedly occurred." Same recipe
  // as #409's CanvasPreview preload cleanup: pause → clear src → load().
  // Capture the ref at mount-time so the cleanup uses the same node we
  // mounted (the ref's .current is stale by unmount).
  useEffect(() => {
    const vid = videoRef.current;
    return () => {
      if (!vid) return;
      vid.pause();
      vid.removeAttribute("src");
      vid.load();
    };
  }, []);

  return (
    <>
      <BrandGradientOverlay
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        seed={gradSeed}
      />

      {showMedia &&
        (resolved === "video" ? (
          <video
            ref={videoRef}
            src={mediaUrl}
            // Poster paints during the decode window so the user sees the
            // (still) first frame instead of a transparent <video> letting
            // the brand gradient show through. Pexels returns a thumbnail
            // image alongside each video; fillPexelsUrls stores it in
            // `variables.mediaPoster`. Layered defense alongside preload="auto"
            // below: on desktop the byte preloader makes decode fast, on
            // mobile (where the preloader skips video pre-mounting to dodge
            // the iOS Safari memory crash) the poster is the primary shield.
            poster={mediaPoster || undefined}
            muted
            loop
            playsInline
            // preload="auto" — without it, browsers default to "metadata":
            // they only load the container/dimensions, not the byte stream
            // needed to decode frames. The element then renders transparent
            // until the first decoded frame arrives, letting the brand
            // gradient flash through whenever a scene mid-playback transitions
            // to a media backdrop. The parent preloader caches the bytes, but
            // decoder state is per-element, so the active mount still has to
            // decode the first frame; "auto" kicks that work off the instant
            // the element mounts.
            preload="auto"
            data-media-position={mediaPosition}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "cover",
              objectPosition: resolvedPosition,
              transform: bgTransform.transform,
              transformOrigin: bgTransform.transformOrigin,
            }}
          />
        ) : (
          <div
            data-media-position={mediaPosition}
            style={{
              position: "absolute",
              inset: 0,
              transform: bgTransform.transform,
              transformOrigin: bgTransform.transformOrigin,
              backgroundImage: `url(${mediaUrl})`,
              backgroundSize: "cover",
              backgroundPosition: resolvedPosition,
            }}
          />
        ))}

      {showMedia &&
        treatmentLayers.map((layer) => (
          <div
            key={layer.id}
            data-media-treatment={resolvedTreatment}
            data-media-overlay={layer.id}
            style={{
              position: "absolute",
              inset: 0,
              background: layer.background,
              pointerEvents: "none",
              ...layer.style,
            }}
          />
        ))}
    </>
  );
};

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares the variables an editor or model may provide
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { ResolvedTokens } from "../theme";
import type { SafeZone, TemplateStyle } from "../template-context";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: TemplateStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** Presentation clock. Active templates receive the same complete 0→1 timeline as progress. */
  motionProgress?: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * Brand tokens already resolved from `style`. Built-in templates import
   * resolveTokens directly; an ejected `custom_*` scene can't import anything,
   * so without this it has no way to reach the same values and ends up
   * hardcoding white, black and shadows — the body then looks generic next to
   * a frame that IS using the brand.
   */
  tokens?: ResolvedTokens;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}
